// Tests of the line length check: node --test .github/scripts/check-line-length.test.mjs

import assert from 'node:assert/strict'
import path from 'node:path'
import { describe, test } from 'node:test'
import {
    findLineLengthProblems,
    findLongLines,
    formatProblem,
    isCheckedPath,
    isGenerated,
    lineLength,
    listTrackedFiles,
    maxLineLength,
    repositoryRoot,
} from './check-line-length.mjs'

const line = (length, start = '') => start + 'x'.repeat(length - start.length)

describe('isCheckedPath', () => {
    test('checks the code of all projects, the themes and the scripts', () => {
        for (const file of [
            'source/WaveMP.Service/Program.cs',
            'tests/WaveMP.Service.Tests/IntegrationTests/UsersApiTests.cs',
            'source/WaveMP.Web/src/App.vue',
            'source/WaveMP.Web/src/stores/player.ts',
            'tests/WaveMP.E2E/tests/library.spec.ts',
            '.github/scripts/check-deploy.mjs',
            'assets/web/themes/midnight/theme.css',
            'source/WaveMP.Service/docker-entrypoint.sh',
        ]) {
            assert.equal(isCheckedPath(file), true, file)
        }
    })

    test('leaves out generated code, packages and files that are not code', () => {
        for (const file of [
            'source/WaveMP.Data/Migrations/20261111090059_AddUsers.cs',
            'source/WaveMP.Data/Migrations/WaveMpDbContextModelSnapshot.cs',
            'source/WaveMP.Web/src/api/generated/models/index.ts',
            'source/WaveMP.Web/node_modules/vue/index.js',
            'README.md',
            'source/WaveMP.Service/openapi.json',
            '.github/workflows/test.yml',
            'Dockerfile',
            'assets/logo/wavemp-logo-default.svg',
        ]) {
            assert.equal(isCheckedPath(file), false, file)
        }
    })
})

describe('isGenerated', () => {
    test('finds the markers of generated files near the start', () => {
        assert.equal(isGenerated('// <auto-generated />\nusing System;\n'), true)
        assert.equal(isGenerated('/* tslint:disable */\n/* eslint-disable */\n// Generated by Microsoft Kiota\n'), true)
    })

    test('ignores a marker further down and files without one', () => {
        assert.equal(isGenerated('a\nb\nc\nd\ne\n// <auto-generated />\n'), false)
        assert.equal(isGenerated('namespace WaveMP.Data;\n'), false)
    })
})

describe('findLongLines', () => {
    test('accepts lines of exactly the limit and reports longer ones with their number and length', () => {
        const text = [line(maxLineLength), line(maxLineLength + 1), '', line(130)].join('\n')

        assert.deepEqual(findLongLines(text), [
            { line: 2, length: 121 },
            { line: 4, length: 130 },
        ])
    })

    test('counts characters, not bytes, and ignores the carriage return of a line', () => {
        const umlauts = 'ä'.repeat(maxLineLength)

        assert.equal(lineLength(`${umlauts}\r`), maxLineLength)
        assert.deepEqual(findLongLines(`${umlauts}\r\n${umlauts}`), [])
    })

    test('allows a comment line that holds nothing but an address', () => {
        const address = `https://example.com/${'a'.repeat(maxLineLength)}`

        assert.deepEqual(findLongLines(`    // ${address}\n    /// ${address}\n     * <${address}>`), [])
        assert.deepEqual(findLongLines(`# ${address}`), [])
    })

    test('reports an address in code or next to other words of a comment', () => {
        const address = `https://example.com/${'a'.repeat(maxLineLength)}`

        assert.deepEqual(
            findLongLines(`const url = '${address}'\n// See ${address}`).map((found) => found.line),
            [1, 2],
        )
    })
})

describe('findLineLengthProblems', () => {
    const files = {
        'source/WaveMP.Core.Library/Long.cs': `namespace X;\n${line(125, '// ')}\n`,
        'source/WaveMP.Core.Library/Short.cs': 'namespace X;\n',
        'source/WaveMP.Data/Migrations/20260101000000_AddX.cs': line(200),
        'source/WaveMP.Data/Generated.cs': `// <auto-generated />\n${line(200)}`,
        'README.md': line(300),
        'assets/web/themes/x/theme.css': `:root {\n${line(121, '    --x: ')}\n}`,
    }

    test('reports the long lines of the checked files only', () => {
        const problems = findLineLengthProblems([...Object.keys(files), 'gone.ts'], (file) => files[file] ?? null)

        assert.deepEqual(problems, [
            { file: 'source/WaveMP.Core.Library/Long.cs', line: 2, length: 125 },
            { file: 'assets/web/themes/x/theme.css', line: 2, length: 121 },
        ])
    })

    test('formats a problem for the terminal and as annotation of GitHub Actions', () => {
        const problem = { file: 'source/A.cs', line: 7, length: 131 }

        assert.equal(formatProblem(problem), 'source/A.cs:7: Line has 131 characters, at most 120 are allowed.')
        assert.equal(
            formatProblem(problem, true),
            '::error file=source/A.cs,line=7::Line has 131 characters, at most 120 are allowed.',
        )
    })
})

describe('listTrackedFiles', () => {
    test('lists the files that git tracks, relative to the root and with forward slashes', () => {
        const files = listTrackedFiles(repositoryRoot)

        assert.ok(files.includes('CLAUDE.md'))
        assert.ok(files.includes('.github/scripts/check-deploy.mjs'))
        assert.ok(files.every((file) => !file.includes('\\') && !path.isAbsolute(file)))
    })
})
